import SwiftUI
struct LoginView: View {
 @EnvironmentObject var store:AppStore; @State var email=""; @State var password=""; @State var name=""; @State var create=false
 var body: some View { NavigationStack { VStack(alignment:.leading,spacing:18) { Spacer(); Text("Dopenexa").font(DopenexaFont.display(38)).foregroundStyle(DopenexaColor.brandDark); Text(create ? "Create your account" : "Welcome back").font(DopenexaFont.title()); if create { TextField("Full name",text:$name).textFieldStyle(.roundedBorder) }; TextField("Email",text:$email).textInputAutocapitalization(.never).keyboardType(.emailAddress).textFieldStyle(.roundedBorder); SecureField("Password",text:$password).textFieldStyle(.roundedBorder); if let error=store.error { Text(error).font(.caption).foregroundStyle(.red) }; Button(create ? "Create account" : "Sign in") { Task { if create { await store.register(email:email,password:password,name:name) } else { await store.login(email:email,password:password) } } }.buttonStyle(DopenexaPrimaryButtonStyle()).disabled(store.isLoading); Button(create ? "I already have an account" : "Create an account") { create.toggle() }.frame(maxWidth:.infinity); Spacer() }.padding(24).background(DopenexaColor.surface.ignoresSafeArea()).navigationBarHidden(true) } }
}
